<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';import MemberManager from'./MemberManager.vue'
const loading=ref(true),courses=ref<any[]>([]),terms=ref<any[]>([]),classes=ref<any[]>([]);const courseForm=reactive({course_name:'',description:''}),termForm=reactive({term_name:''}),classForm=reactive({course_id:'',term_id:'',class_name:''})
async function load(){loading.value=true;try{[courses.value,terms.value,classes.value]=(await Promise.all([api.get('/teacher/courses'),api.get('/teacher/terms'),api.get('/teacher/classes')])).map(x=>x.data)}finally{loading.value=false}}
async function createCourse(){await api.post('/teacher/courses',courseForm);Object.assign(courseForm,{course_name:'',description:''});ElMessage.success('课程已创建');await load()}async function createTerm(){await api.post('/teacher/terms',termForm);termForm.term_name='';ElMessage.success('学期已创建');await load()}async function createClass(){await api.post('/teacher/classes',classForm);Object.assign(classForm,{course_id:'',term_id:'',class_name:''});ElMessage.success('教学班已创建');await load()}onMounted(load)
</script>
<template><main class="content" v-loading="loading"><div class="page-title"><span class="eyebrow">COURSES & CLASSES</span><h1>课程与教学班</h1><p class="muted">课程、学期、教学班和学生授权集中管理。</p></div><el-row :gutter="20"><el-col :span="14"><el-card shadow="never"><template #header><b>教学班</b></template><el-table :data="classes"><el-table-column prop="course_name" label="课程"/><el-table-column prop="class_name" label="教学班"/><el-table-column prop="term_name" label="学期"/><el-table-column prop="member_count" label="成员"/></el-table></el-card><MemberManager/></el-col><el-col :span="10"><el-card shadow="never"><template #header><b>创建教学范围</b></template><el-tabs><el-tab-pane label="课程"><el-form label-position="top"><el-form-item label="课程名称"><el-input v-model="courseForm.course_name"/></el-form-item><el-form-item label="说明"><el-input v-model="courseForm.description" type="textarea"/></el-form-item><el-button type="primary" @click="createCourse">创建</el-button></el-form></el-tab-pane><el-tab-pane label="学期"><el-input v-model="termForm.term_name" placeholder="2026 秋季学期"/><el-button class="form-button" type="primary" @click="createTerm">创建</el-button></el-tab-pane><el-tab-pane label="教学班"><el-form label-position="top"><el-form-item label="课程"><el-select v-model="classForm.course_id"><el-option v-for="x in courses" :key="x.course_id" :label="x.course_name" :value="x.course_id"/></el-select></el-form-item><el-form-item label="学期"><el-select v-model="classForm.term_id"><el-option v-for="x in terms" :key="x.term_id" :label="x.term_name" :value="x.term_id"/></el-select></el-form-item><el-form-item label="名称"><el-input v-model="classForm.class_name"/></el-form-item><el-button type="primary" @click="createClass">创建</el-button></el-form></el-tab-pane></el-tabs></el-card></el-col></el-row></main></template>
